import java.util.*;

class Solution {
    public int numSubarrayProductLessThanK(int[] nums, int k) {
        if (k <= 1) return 0;          // every product is at least 1
        long prod = 1;
        int left = 0, count = 0;
        for (int right = 0; right < nums.length; right++) {
            prod *= nums[right];
            while (prod >= k) prod /= nums[left++]; // shrink until the product is below k
            count += right - left + 1;              // runs ending at right
        }
        return count;
    }
}

