function numSubarrayProductLessThanK(nums, k) {
  let c = 0;
  for (let i = 0; i < nums.length; i++) { let p = 1; for (let j = i; j < nums.length; j++) { p *= nums[j]; if (p >= k) break; c++; } }
  return c;
}
